"""Prepare self-contained Kusto checks using the public collection-conversion API.

Run from the repository root with PYTHONPATH=. python tests/fixtures/correlation/generate.py.
The expected rows below are worked examples, independent of the generated query.
"""

from pathlib import Path

import yaml

from sigma.backends.kusto import KustoBackend
from sigma.collection import SigmaCollection
from sigma.pipelines.kusto_common.schema import FieldMappings
from sigma.processing.pipeline import ProcessingPipeline

DESTINATION = Path(__file__).parent


def query(*, operator="gte", threshold=2, groups=(), duplicate_sources=False, counted_field=None, mapped_sources=False):
    source = {
        "title": "Fixture source",
        "name": "source-rule",
        "logsource": {"product": "fixture"},
        "detection": {
            "selection": {"Marker": "match"},
            "alternate": {"Marker": "match"},
            "condition": ["selection", "alternate"] if duplicate_sources else "selection",
        },
    }
    documents = [source]
    references = ["source-rule"]
    if duplicate_sources or mapped_sources:
        documents.append(
            {
                **source,
                "title": "Other fixture source",
                "name": "other-rule",
                "logsource": {"product": "other-fixture" if mapped_sources else "fixture"},
            }
        )
        references.append("other-rule")
    condition = {operator: threshold}
    if counted_field is not None:
        condition["field"] = counted_field
    documents.append(
        {
            "title": "Fixture correlation count",
            "correlation": {
                "type": "event_count" if counted_field is None else "value_count",
                "rules": references,
                "group-by": list(groups),
                "timespan": "5m",
                "condition": condition,
            },
        }
    )
    if mapped_sources:
        documents[-1]["correlation"]["aliases"] = {
            "Actor": {"source-rule": "User", "other-rule": "Account"},
            "Host": {"source-rule": "Computer", "other-rule": "Device"},
            "Target": {"source-rule": "File", "other-rule": "Destination"},
        }
    collection = SigmaCollection.from_yaml(yaml.safe_dump_all(documents))
    transformations = [{"type": "set_state", "key": "query_table", "val": "Events"}]
    if mapped_sources:
        transformations.append(
            {
                "type": "set_state",
                "key": "query_table",
                "val": "OtherEvents",
                "rule_conditions": [{"type": "logsource", "product": "other-fixture"}],
            }
        )
    pipeline = ProcessingPipeline.from_dict({"transformations": transformations})
    if mapped_sources:
        pipeline.vars["kusto_field_mappings"] = FieldMappings(
            table_mappings={
                "Events": {
                    "Timestamp": "ProcessTime",
                    "User": "ProcessUser",
                    "Computer": "ProcessHost",
                    "File": "ProcessTarget",
                },
                "OtherEvents": {
                    "Timestamp": "NetworkTime",
                    "Account": "NetworkUser",
                    "Device": "NetworkHost",
                    "Destination": "NetworkTarget",
                },
            }
        )
    (converted,) = KustoBackend(processing_pipeline=pipeline, correlation_timestamp_field="Timestamp").convert(
        collection
    )
    return converted


def check(actual, expected, fields):
    """An empty result means exact multiset equality, including result multiplicity."""
    return (
        f"union ({actual} | extend Delta = 1), ({expected} | extend Delta = -1)\n"
        f"| summarize Delta = sum(Delta) by {', '.join(fields)}\n"
        "| where Delta != 0\n"
    )


HEADER = """// Prepared deterministic fixture; live engine execution has not been performed.
// Generated by tests/fixtures/correlation/generate.py via KustoBackend.convert().
// Run the entire file in one Kusto query. PASS = zero output rows.
// Nonempty rows identify a missing, additional, or duplicated summary.
"""


